/**
 * Task 0.5 static camera-ownership audit. This is evidence, not a runtime
 * controller: it documents the active App → AsyncCesiumGlobe → CesiumGlobe path.
 */
export type CameraTransitionId = 'initial-space-frame' | 'intro-overview' | 'region-sync' | 'guided-tour' | 'pre-render-auto-pitch' | 'viewport-resize' | 'mouse-inspection' | 'touch-inspection';
export type CameraApi = 'setView' | 'flyTo' | 'flyToBoundingSphere' | 'cancelFlight';
export type TransitionKind = 'camera-write' | 'layout-only' | 'interaction-only';
export interface CameraTransitionAuditEntry {
  id: CameraTransitionId; kind: TransitionKind; caller: string; trigger: string; source: string;
  cameraCalls: readonly CameraApi[]; currentPriority: string; cancellation: string; completion: string;
  manualInteractionBehavior: string; conflicts: readonly string[];
}

export const CAMERA_TRANSITION_TABLE: readonly CameraTransitionAuditEntry[] = [
  { id: 'initial-space-frame', kind: 'camera-write', caller: 'CesiumGlobe initialization', trigger: 'Viewer creation on component mount.', source: 'components/CesiumGlobe.tsx: viewer.camera.setView (initialization)', cameraCalls: ['setView'], currentPriority: 'Mount-time synchronous write; no global priority and any later writer can supersede it.', cancellation: 'Does not call cancelFlight.', completion: 'Synchronous setView; no callback or state transition.', manualInteractionBehavior: 'Occurs before normal input is available; does not establish a manual-input lock.', conflicts: ['The independently timed intro overview replaces this frame after 800ms.'] },
  { id: 'intro-overview', kind: 'camera-write', caller: 'CesiumGlobe cinematic timer', trigger: 'Unconditional 800ms timeout after viewer initialization; not connected to CinematicIntro visibility, skip, reduced motion, or completion.', source: 'components/CesiumGlobe.tsx: introFlyTimer → flyCameraToBounds', cameraCalls: ['cancelFlight', 'flyToBoundingSphere'], currentPriority: 'Scheduled last-writer-wins: when its timeout fires it cancels any active programmatic flight, including an early region selection.', cancellation: 'flyCameraToBounds unconditionally calls cancelFlight before starting its own flight.', completion: 'flyToBoundingSphere complete or cancel callback clears isCameraAnimatingRef.', manualInteractionBehavior: 'No user-input gate; a user interaction before the timer fires cannot prevent the overview flight.', conflicts: ['Can override a region flight started during the first 800ms.', 'CinematicIntro is a visual overlay only, so skip/dismiss does not control this timer.'] },
  { id: 'region-sync', kind: 'camera-write', caller: 'Region effect from App selectedRegion / regionFlyTrigger', trigger: 'Effect runs after readiness when region or regionFlyTrigger changes; first default run returns unless a non-zero trigger is already present.', source: 'App.tsx: RegionSelector onChange; components/CesiumGlobe.tsx: region-sync effect', cameraCalls: ['cancelFlight', 'flyToBoundingSphere'], currentPriority: 'No explicit priority; this caller wins only if it starts last among programmatic callers.', cancellation: 'flyCameraToBounds unconditionally cancels the active flight, without checking source or intent.', completion: 'flyToBoundingSphere complete or cancel callback clears isCameraAnimatingRef; no App completion signal.', manualInteractionBehavior: 'No manual-interaction ref or cooldown suppresses the flight.', conflicts: ['A later intro timeout can replace it.', 'A tour step can replace it; the tour remains active and can later fly again.'] },
  { id: 'guided-tour', kind: 'camera-write', caller: 'App handleTourStep → GuidedTour step effect', trigger: 'Tour activation, step controls, dots, or auto-advance updates tourStep; App mounts both a header instance and overlay instance when active.', source: 'components/GuidedTour.tsx; App.tsx: handleTourStep; components/CesiumGlobe.tsx: tour effect → flyCameraTo', cameraCalls: ['cancelFlight', 'flyTo'], currentPriority: 'No explicit priority; this caller wins only if it starts last among programmatic callers.', cancellation: 'flyCameraTo unconditionally cancels the active flight before flyTo; closing the tour only clears tourStep and does not cancel an already-running flight.', completion: 'flyTo complete or cancel callback clears isCameraAnimatingRef; auto-advance uses duration + 3 seconds, not the completion callback.', manualInteractionBehavior: 'No manual-input gate or cooldown; Cesium default input is not coordinated by application state.', conflicts: ['Can cancel region or intro flights.', 'Two mounted GuidedTour instances can emit duplicate step-zero requests.', 'Region selection does not stop the tour schedule.'] },
  { id: 'pre-render-auto-pitch', kind: 'camera-write', caller: 'Cesium scene.preRender listener', trigger: 'Every render while camera height exceeds 4,000,000m and isCameraAnimatingRef is false.', source: 'components/CesiumGlobe.tsx: scene.preRender auto-center listener', cameraCalls: ['setView'], currentPriority: 'Per-frame idle writer: it yields only to the local programmatic-animation flag, not to people.', cancellation: 'Does not call cancelFlight and cannot cancel a flight; it returns while the local animation flag is true.', completion: 'No terminal callback; each render may write another pitch correction.', manualInteractionBehavior: 'Manual high-altitude rotate/tilt/zoom is not detected, so this continuously changes pitch during user interaction.', conflicts: ['Directly competes with manual camera orientation once no programmatic flight is active.', 'May resume immediately after any programmatic completion/cancel callback.'] },
  { id: 'viewport-resize', kind: 'layout-only', caller: 'App ResizeObserver/window resize → viewportKey effect', trigger: 'Measured header/timeline/drawer changes update viewportKey; Cesium effect calls resize and requestRender.', source: 'App.tsx: useLayoutEffect measurement; components/CesiumGlobe.tsx: viewportKey effect', cameraCalls: [], currentPriority: 'No camera ownership: layout-only update.', cancellation: 'Does not call cancelFlight or start a camera transition.', completion: 'viewer.resize then scene.requestRender; no camera completion callback.', manualInteractionBehavior: 'Preserves orientation in local code, but can render during a flight and therefore exposes the current preRender/flight races.', conflicts: ['No safe-area-aware reframe exists, so resizing does not deliberately preserve a target framing.'] },
  { id: 'mouse-inspection', kind: 'interaction-only', caller: 'Cesium ScreenSpaceEventHandler', trigger: 'Mouse move tracks coordinates; LEFT_CLICK inspects a cell or toggles App focus mode on empty sky.', source: 'components/CesiumGlobe.tsx: MOUSE_MOVE and LEFT_CLICK handlers', cameraCalls: [], currentPriority: 'No application camera priority or ownership signal.', cancellation: 'No explicit cancelFlight call.', completion: 'Picking callback returns synchronously; no camera completion path.', manualInteractionBehavior: 'Does not suppress Cesium default mouse camera controls and does not mark interaction/cooldown.', conflicts: ['Does not prevent preRender auto-pitch from changing a high-altitude manual orientation.'] },
  { id: 'touch-inspection', kind: 'interaction-only', caller: 'Canvas pointer listeners plus Cesium camera controller', trigger: 'Touch pointerdown/move/up/cancel implements 600ms one-finger long press; Cesium zoom/rotate/tilt remains enabled.', source: 'components/CesiumGlobe.tsx: pointer handlers and screenSpaceCameraController setup', cameraCalls: [], currentPriority: 'No application camera priority or ownership signal.', cancellation: 'No explicit cancelFlight call; multi-touch or movement only cancels the long-press timer.', completion: 'Long-press calls inspection callback; camera motion remains Cesium-controller behavior with no App signal.', manualInteractionBehavior: 'touchAction none and enabled Cesium controls permit pan/pinch, but no manual ref/cooldown blocks automated camera writes.', conflicts: ['preRender auto-pitch can write while a high-altitude touch gesture is in progress.'] },
] as const;

export const REQUIRED_CAMERA_TRANSITION_IDS: readonly CameraTransitionId[] = ['initial-space-frame', 'intro-overview', 'region-sync', 'guided-tour', 'pre-render-auto-pitch', 'viewport-resize', 'mouse-inspection', 'touch-inspection'] as const;
export const REQUIRED_ACTIVE_CAMERA_API_CALLS: readonly CameraApi[] = ['setView', 'flyTo', 'flyToBoundingSphere', 'cancelFlight'] as const;
export const CAMERA_AUDIT_LIMITATIONS = ['Static audit only: it records source behavior and does not simulate Cesium input cancellation.', 'features/globe/CesiumGlobe.tsx also contains setView/setView/flyTo, but App imports components/AsyncCesiumGlobe and no active production import of the plugin shell was found.'] as const;
export function cameraTransitionById(id: CameraTransitionId): CameraTransitionAuditEntry { const entry = CAMERA_TRANSITION_TABLE.find((candidate) => candidate.id === id); if (!entry) throw new Error(`Missing camera transition audit entry: ${id}`); return entry; }
